"""Rewrite docs/space-budget.md from the fit model."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from mechanical.manent_mech import stack as S          # noqa: E402
from mechanical.manent_mech.checks import full_report, sensitivity  # noqa: E402

rep = full_report()
o = ["# Space budget", "",
     "Generated by `tools/space_budget.py` from the model in `mechanical/`. Lengths in millimetres.",
     "Part sizes come from `parts/parts.yaml`; several are still unverified there, and the cell",
     "figures are catalogue values, not a supplier's drawing.", "",
     "## Rules the model applies", "",
     "- Titanium shell 0.40 thick on the outer face, the side walls and round the corners; resin skin 0.35",
     "  towards the finger, in the window between the two inner corners.",
     "- At least 0.10 of resin around every part.",
     f"- Cell: {S.SWELL:.0%} thickness growth allowed for, plus {S.CELL_GAP} of wrap on each side.",
     f"- Flex {S.FLEX_WIDTH} wide; islands {S.RIGID_T} thick, joined by {min(S.BENDS)} to {max(S.BENDS)} of bare flex; "
     f"{S.CELL_TABS} for the cell tabs.",
     "- Each bend must be long enough to span the step in depth between its two islands, and fold no tighter",
     "  than ten times the flex thickness.",
     "- Every part in the bill of materials is placed, on one of the two faces of an island, in columns",
     f"  across the flex, {S.PART_SPACING} apart, with extra room around the fine-pitch packages. This checks that",
     "  the parts have room; it does not check that the tracks between them can be routed.",
     f"- Charging and service contacts: a slug on each pad, {S.SLUG_D['Pad_Charge_D1.5']} or {S.SLUG_D['Pad_Service_D0.8']} across, comes up to the inner",
     f"  surface and stays {S.SLUG_LIP} or more from the titanium. A steel keeper sits {0.10:.2f} above the parts of that island.",
     f"- The button sits at {S.BUTTON_DEG:.0f} degrees, towards the thumb; microphone and light must land on the back",
     "  of the finger (60 to 120 degrees). Arc left over lies between the antenna and the far end of the cell.", ""]
for key, e in rep["envelopes"].items():
    o += [f"## Envelope {e['envelope']}: {e['band_width']} wide, wall {e['wall_edge']} to {e['wall_centre']}", "",
          f"Reference finger: inner diameter {e['inner_diameter']} (US {e['us_size']}), outer diameter {e['outer_diameter']}.",
          f"**Result: {'everything fits' if e['ok'] else 'does not fit'}.**", "",
          "Cavity height available to a centred part, by part width: "
          + ", ".join(f"{w} wide: {h}" for w, h in e["cavity_height"].items()) + ".", "",
          "| Island | Length | Stack height | Resin left around it | Centre at | Result |", "| --- | --- | --- | --- | --- | --- |"]
    place = {p["island"]: p["centre_deg"] for p in e["arc"]["placed"]}
    o += [f"| {i['island']} | {i['length']} | {i['stack_height']:.2f} | {i['clearance']:.2f} | {place[i['island']]:.0f} deg | "
          f"{'fits' if i['ok'] else 'FAILS ' + '; '.join(i['problems'])} |" for i in e["islands"]]
    c, a, m = e["cell"], e["arc"], e["mass"]
    o += ["", f"- **Cell**: {c['mpn']}, {c['size'][0]} x {c['size'][1]} x {c['size'][2]}, {c['capacity_mah']} mAh. "
              f"Room left on each side after swelling: {c['clearance']:.2f} "
              f"({'enough' if c['ok'] else 'less than the ' + str(S.CELL_GAP) + ' required'}). It spans {c['arc_deg']} degrees.",
          f"- **Arc**: electronics take {a['electronics_mm']} of arc; {a['slack_mm']:+.1f} is left over.",
          f"- **Contacts**: slugs {e['contacts']['shortest']:.2f} to {e['contacts']['tallest']:.2f} tall from pad to inner surface, "
          f"{e['contacts']['closest_to_titanium']:.2f} from the titanium, {e['contacts']['closest_pair']:.2f} from each other. "
          f"The steel keeper ({' x '.join(str(v) for v in e['contacts']['keeper']['size'])}) keeps "
          f"{e['contacts']['keeper']['resin_to_shell']:.2f} of resin to the shell"
          f"{'' if e['contacts']['ok'] else ' (**fails**)'}.",
          f"- **Mass** (estimate): titanium {m['titanium_g']} g, total about {m['total_g_estimate']} g.",
          f"- Drawings: [plan](../mechanical/out/plan-{key}.svg), "
          f"[audio island section](../mechanical/out/section-{key}-audio.svg), "
          f"[SoC island section](../mechanical/out/section-{key}-soc.svg).", ""]
o += ["## Ring sizes", "",
      "The electronics need the same arc on every finger, so the cell gets what is left.", "",
      "| US size | Inner diameter | Longest cell | Best catalogue cell, 7.4 band | Best catalogue cell, 8.0 band |",
      "| --- | --- | --- | --- | --- |"]
for ra, rb in zip(rep["size_sweep"]["A"], rep["size_sweep"]["B"]):
    f = lambda r: f"{r['best_cell']} ({r['capacity_mah']} mAh)" if r["best_cell"] else "none"
    o.append(f"| {ra['us_size']} | {ra['inner_diameter']} | {rb['max_cell_length']} | {f(ra)} | {f(rb)} |")
o += ["", "Only the 1.6 x 6.0 cell passes the cross-section check, and it comes in one length (26). Where the table",
      "shows room for a longer one, more capacity needs a cell made to order: roughly 0.6 mAh per millimetre,",
      "by proportion.", "",
      "## How much margin there is", "",
      "The two least certain numbers are the thickness of the rigid islands (an estimate until a fabricator",
      "gives a stack-up) and how much the cell swells over its life. Margin is what is left beyond the rule,",
      "on the 8.0 band.", "",
      "| Assumption | Margin | Result |", "| --- | --- | --- |"]
o += [f"| {r['what']} | {r['margin']:+.3f} | {'fits' if r['ok'] else 'does not fit'} |" for r in sensitivity()]
o.append("")
(ROOT / "docs" / "space-budget.md").write_text("\n".join(o))
print("docs/space-budget.md written")
